def test_trigger_salvo_structure_scalar():
    """All count=1 ports use NonEmpty state."""
    config = get_node_config(ports=["a", "b"])
    trigger = config.in_salvo_conditions["trigger"]

    assert isinstance(trigger.term, SalvoConditionTermAndConfig)
    assert len(trigger.term.terms) == 2

    for term in trigger.term.terms:
        assert isinstance(term, SalvoConditionTermPortConfig)
        assert isinstance(term.state, PortStateNonEmptyConfig)

    assert trigger.ports == {
        "a": PacketCountNConfig(count=1),
        "b": PacketCountNConfig(count=1),
    }
    assert trigger.max_salvos.max == 1


def test_trigger_salvo_structure_batch():
    """Ports with count>1 use EqualsOrGreaterThan state."""
    config = get_node_config(ports={"single": 1, "multi": 3})
    trigger = config.in_salvo_conditions["trigger"]

    assert isinstance(trigger.term, SalvoConditionTermAndConfig)
    terms_by_port = {t.port_name: t for t in trigger.term.terms}

    assert isinstance(terms_by_port["single"].state, PortStateNonEmptyConfig)
    assert isinstance(terms_by_port["multi"].state, PortStateEqualsOrGreaterThanConfig)
    assert terms_by_port["multi"].state.value == 3

    assert trigger.ports["single"] == PacketCountNConfig(count=1)
    assert trigger.ports["multi"] == PacketCountNConfig(count=3)


def test_output_salvo():
    """Output salvo sends all from 'out' port."""
    config = get_node_config(ports=["a"])
    send = config.out_salvo_conditions["send"]
    assert "out" in send.ports
    assert isinstance(send.ports["out"], PacketCountAllConfig)

