# %% pts/tests/07_node_factories/test_join.pct.py 12
from netrun.net.config import (
    NetConfig,
    NodeConfig as NC,
    NodeExecutionConfig,
    PortConfig,
    GraphConfig,
    EdgeConfig,
    SalvoConditionConfig,
    SalvoConditionTermTrueConfig,
    MaxSalvosFiniteConfig,
    PacketCountAllConfig as PCA,
    PacketCountNConfig as PCN,
    PoolConfig,
    OutputQueueConfig,
)
from netrun.net.config._net_config import MainPoolConfig
from netrun.net._net._net import Net


def _source_exec(value):
    """Create an exec function that outputs a fixed value."""
    def exec_func(ctx, packets):
        for pid in packets.get("trigger", []):
            ctx.consume_packet(pid)
        p = ctx.create_packet(value)
        ctx.load_output_port("out", p)
        ctx.send_output_salvo("send")
    return exec_func


def _source_node(name: str, exec_func, out_port: str = "out") -> NC:
    """A trivial source node with one output port and an exec function."""
    return NC(
        name=name,
        in_ports={"trigger": PortConfig()},
        out_ports={out_port: PortConfig()},
        in_salvo_conditions={
            "go": SalvoConditionConfig(
                max_salvos=MaxSalvosFiniteConfig(max=1),
                ports={"trigger": PCN(count=1)},
                term=SalvoConditionTermTrueConfig(),
            ),
        },
        out_salvo_conditions={
            "send": SalvoConditionConfig(
                max_salvos=MaxSalvosFiniteConfig(max=1),
                ports={out_port: PCA()},
                term=SalvoConditionTermTrueConfig(),
            ),
        },
        execution_config=NodeExecutionConfig(
            node_name=name,
            pools=["main"],
            exec_node_func=exec_func,
        ),
    )


def _join_node_with_exec(ports):
    """Create a join NodeConfig with its exec function attached."""
    join_cfg = get_node_config(ports=ports)
    join_exec = get_node_funcs(ports=ports)[0]
    join_cfg.execution_config = NodeExecutionConfig(
        node_name="join",
        pools=["main"],
        exec_node_func=join_exec,
    )
    return join_cfg

# %% pts/tests/07_node_factories/test_join.pct.py 13
@pytest.mark.asyncio
async def test_join_two_sources():
    """Two sources feed into a join; output is a dict of their values."""
    config = NetConfig(
        pools={"main": PoolConfig(spec=MainPoolConfig())},
        graph=GraphConfig(
            nodes=[
                _source_node("src_a", _source_exec("hello")),
                _source_node("src_b", _source_exec(42)),
                _join_node_with_exec(["left", "right"]),
            ],
            edges=[
                EdgeConfig(source_str="src_a.out", target_str="join.left"),
                EdgeConfig(source_str="src_b.out", target_str="join.right"),
            ],
        ),
        output_queues={"results": OutputQueueConfig(ports=[("join", "out")])},
    )

    async with Net(config) as net:
        net.inject_data("src_a", "trigger", [None])
        net.inject_data("src_b", "trigger", [None])

        await net.run_until_blocked()

        results = net.flush_output_queue("results")
        assert len(results) == 1
        assert results[0] == {"left": "hello", "right": 42}

# %% pts/tests/07_node_factories/test_join.pct.py 14
@pytest.mark.asyncio
async def test_join_batch_port():
    """A join port with count>1 collects multiple packets into a list."""
    def src_batch_exec(ctx, packets):
        for pid in packets.get("trigger", []):
            ctx.consume_packet(pid)
        for val in ["first", "second"]:
            p = ctx.create_packet(val)
            ctx.load_output_port("out", p)
        ctx.send_output_salvo("send")

    config = NetConfig(
        pools={"main": PoolConfig(spec=MainPoolConfig())},
        graph=GraphConfig(
            nodes=[
                _source_node("src_scalar", _source_exec("only_one")),
                _source_node("src_batch", src_batch_exec),
                _join_node_with_exec({"scalar": 1, "batch": 2}),
            ],
            edges=[
                EdgeConfig(source_str="src_scalar.out", target_str="join.scalar"),
                EdgeConfig(source_str="src_batch.out", target_str="join.batch"),
            ],
        ),
        output_queues={"results": OutputQueueConfig(ports=[("join", "out")])},
    )

    async with Net(config) as net:
        net.inject_data("src_scalar", "trigger", [None])
        net.inject_data("src_batch", "trigger", [None])

        await net.run_until_blocked()

        results = net.flush_output_queue("results")
        assert len(results) == 1
        assert results[0]["scalar"] == "only_one"
        assert isinstance(results[0]["batch"], list)
        assert len(results[0]["batch"]) == 2
        assert set(results[0]["batch"]) == {"first", "second"}
